#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    int n, k;
    scanf("%d %d", &n, &k);
    vector<ll> rates(n), con(n);
    for (auto &x : rates) scanf("%lld", &x);
    ll baseline = 0;
    for (int i = 0; i < n; i++) {
        ll s;
        scanf("%lld", &s);
        con[i] = rates[i] * s;
        baseline += con[i];
    }
    int half = k / 2;
    // old: original contribution of the window; rep: price sum of its second half.
    ll old = 0, rep = 0;
    for (int i = 0; i < k; i++) old += con[i];
    for (int i = half; i < k; i++) rep += rates[i];
    ll best = max(0LL, rep - old);
    for (int left = 0; left < n - k; left++) {
        old += con[left + k] - con[left];
        rep += rates[left + k] - rates[left + half];
        best = max(best, rep - old);
    }
    printf("%lld\n", baseline + best);
}

import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), k = nextInt();
        long[] rates = new long[n], con = new long[n];
        for (int i = 0; i < n; i++) rates[i] = nextLong();
        long baseline = 0;
        for (int i = 0; i < n; i++) {
            con[i] = rates[i] * nextLong();
            baseline += con[i];
        }
        int half = k / 2;
        // old: original contribution of the window; rep: price sum of its second half.
        long old = 0, rep = 0;
        for (int i = 0; i < k; i++) old += con[i];
        for (int i = half; i < k; i++) rep += rates[i];
        long best = Math.max(0, rep - old);
        for (int left = 0; left < n - k; left++) {
            old += con[left + k] - con[left];
            rep += rates[left + k] - rates[left + half];
            best = Math.max(best, rep - old);
        }
        System.out.println(baseline + best);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := int(nextInt()), int(nextInt())
	rates := make([]int64, n)
	con := make([]int64, n)
	for i := range rates {
		rates[i] = nextInt()
	}
	var baseline int64
	for i := 0; i < n; i++ {
		con[i] = rates[i] * nextInt()
		baseline += con[i]
	}
	half := k / 2
	// old: original contribution of the window; rep: price sum of its second half.
	var old, rep int64
	for i := 0; i < k; i++ {
		old += con[i]
	}
	for i := half; i < k; i++ {
		rep += rates[i]
	}
	best := max(0, rep-old)
	for left := 0; left < n-k; left++ {
		old += con[left+k] - con[left]
		rep += rates[left+k] - rates[left+half]
		best = max(best, rep-old)
	}
	fmt.Println(baseline + best)
}
